PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorName (MAX(xsd:decimal(?allocationPct)) AS ?maxAllocation)
WHERE {
  ?sectorAllocation a ex:SectorAllocation ;
                     ex:hasInvestor ?investor ;
                     ex:sectorName ?sectorName ;
                     ex:allocationPct ?allocationPct .
  FILTER(CONTAINS(LCASE(STR(?investor)), "INV001"))
}
GROUP BY ?sectorName
ORDER BY DESC(?maxAllocation)
LIMIT 1

